// Run against a freshly reset session at desktop and mobile widths.
(async () => {
  const wait = () => new Promise((r) => setTimeout(r, 140));
  const check = (value, text) => { if (!value) throw Error(text); };
  const state = () => JSON.parse(localStorage.getItem("collaboration-prototype-v1"));
  const go = async (path) => { location.hash = path; await wait(); };
  const visible = (el) => el.getClientRects().length > 0;
  const click = async (text, scope = document) => {
    const button = [...scope.querySelectorAll("button,a")].find((el) => visible(el) && (el.textContent.trim() === text || el.getAttribute("aria-label") === text));
    check(button, `Missing control ${text}`); button.click(); await wait();
  };
  const pane = async (name) => { if (innerWidth <= 760) await click(name, document.querySelector(".org-mobile-panes")); };
  const fill = async (label, value) => {
    const field = [...document.querySelectorAll(".org-editor .field,dialog .field")].find((el) => el.querySelector("label")?.textContent.replace(" *", "").trim() === label);
    const input = field?.querySelector("input:not([type=hidden]),textarea"); check(input, `Missing field ${label}`);
    const proto = input.tagName === "TEXTAREA" ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
    Object.getOwnPropertyDescriptor(proto, "value").set.call(input, value); input.dispatchEvent(new Event("input", { bubbles: true })); await wait();
  };
  const choose = async (label, value) => { document.querySelector(`[role=combobox][aria-label="${label}"]`).click(); await wait(); await click(value, document.querySelector("[role=listbox]")); };
  const toggle = async (label) => { const box = document.querySelector(`.org-editor input[aria-label="${label}"]`); check(box, label); box.click(); await wait(); };
  const save = async () => { await fill("变更说明", "浏览器核对组织责任"); await click("保存", document.querySelector(".org-editor")); };
  const treeNode = async (name) => { await pane("组织"); const button = [...document.querySelectorAll(".org-tree-row")].find((el) => el.querySelector("span")?.textContent === name); check(button, name); button.click(); await wait(); };
  const selectRow = async (name) => { await pane("列表"); const button = [...document.querySelectorAll(".org-person-row")].find((el) => el.querySelector("strong")?.textContent === name); check(button, name); button.click(); await wait(); };
  await go("/members");
  await pane("组织"); await click("新增部门 / 团队"); await fill("组织节点名称", "浏览器团队");
  await choose("上级组织", "产品与工程"); await toggle("正式成员 林予"); await save();
  let node = state().organization.nodes.find((n) => n.name === "浏览器团队");
  check(node.parentId === "ORG-engineering" && node.memberIds.includes("H-lin"), "Create hierarchy failed");
  await treeNode("浏览器团队"); await click("编辑 / 移动 浏览器团队"); await choose("上级组织", "品牌与创意"); await save();
  node = state().organization.nodes.find((n) => n.id === node.id); check(node.parentId === "ORG-creative" && node.history.length === 2, "Move history missing");
  await treeNode("组织"); await click("编辑 / 移动 组织"); await choose("上级组织", "浏览器团队"); await save();
  check(document.querySelector(".org-editor").textContent.includes("循环"), "Cycle not blocked"); await click("取消", document.querySelector(".org-editor"));
  check(document.querySelector('dialog[aria-label="放弃未保存的修改？"]'), "Rejected organization edit lost discard guard"); await click("放弃修改");
  await treeNode("全部成员"); await selectRow("林予");
  const attribution = JSON.stringify(state().organization.nodes);
  await click("添加项目角色"); await choose("所属项目", state().projects[1].name); await choose("项目职责", "评审者"); await save();
  check(JSON.stringify(state().organization.nodes) === attribution, "Project role changed formal membership");
  await pane("列表");
  check([...document.querySelectorAll(".org-person-row .org-row-tag")].every(el => el.textContent === "Human"), "Agent appeared in Human organization");
  check(!document.querySelector(".org-tabs").textContent.includes("工作小团队"), "Task team remained under organization");
  check(location.hash.split("?")[0] === "#/members", "Organization actions navigated away");
  const roster = JSON.stringify(state().organization.members);
  await click("邀请成员"); await fill("姓名", "邀请验收"); await fill("电子邮件", "invite@example.test");
  await choose("邀请人", "许言"); await choose("邀请项目", state().projects[1].name); await choose("项目角色", "外部客户");
  await fill("邀请说明", "仅查看选定项目已共享成果"); await click("创建本地邀请", document.querySelector(".org-editor"));
  const invitation = state().resources.invitations.find((item) => item.name === "邀请验收");
  check(invitation?.status === "待接受" && invitation.projectId === state().projects[1].id && invitation.owner === "许言" && invitation.scopeKind === "shared", "Invitation scope or inviter wrong");
  check(JSON.stringify(state().organization.members) === roster, "Pending invitation added member");
  await selectRow("邀请验收"); await click("撤销邀请"); await fill("撤销原因", "调整合作范围"); await click("确认撤销", document.querySelector(".org-editor"));
  check(state().resources.invitations.find((item) => item.id === invitation.id).status === "已撤销", "Invitation not revoked");
  check(location.hash.split("?")[0] === "#/members", "Invitation actions left organization page");
  await go(`/invitations/${invitation.id}`);
  check(document.querySelector(".org-detail").textContent.includes("邀请验收") && document.querySelector(".org-detail").textContent.includes("已撤销"), "Invitation deep link lost scoped detail");
  await go("/invitations");
  check(document.querySelector(".org-tabs .active").textContent === "邀请记录" && !document.querySelector(".resource-grid"), "Legacy invitation entry bypasses scoped management");
  for (const details of document.querySelectorAll(".org-history")) details.open = true;
  check(document.documentElement.scrollWidth <= innerWidth + 1, "Horizontal overflow");
  document.querySelector(".tenant-trigger").click(); await wait(); await click("创建租户");
  await fill("租户名称", "组织隔离验收"); await click("创建并进入", document.querySelector("dialog")); await go("/members");
  check(state().organization.nodes.length === 0 && state().organization.members.length === 1 && state().organization.members[0].id === "H-lin" && state().agents.length === 0, "Empty tenant leaked organization");
  check(!document.querySelector("main").textContent.includes("周宁") && !document.querySelector("main").textContent.includes("许言"), "Empty roster leaked other studio members");
  await click("添加成员"); await fill("演示成员名称", "本地负责人"); await save();
  await pane("组织"); await click("新增部门 / 团队"); await fill("组织节点名称", "本地组织"); await toggle("正式成员 本地负责人"); await save();
  check(state().organization.nodes[0].memberIds.length === 1 && state().organization.members.length === 2, "Empty tenant explicit setup failed");
  check(document.documentElement.scrollWidth <= innerWidth + 1, "Empty tenant overflow");
  return { pass: true, checks: ["three-pane mobile navigation", "hierarchy create/move/cycle/history", "independent project roles", "Human-only roster and task-team separation", "scoped local invitation/revocation", "same-page actions", "empty-tenant isolation"] };
})();
